/**
 * The drift guard between the Rust figure core and its TypeScript mirror:
 * `crates/manang-figure/tests/fixtures/parity.json` is generated by Rust
 * (`tests/parity.rs`); every case must come out the same here.
 */

import { describe, expect, it } from "vitest";

import fixture from "../../../crates/manang-figure/tests/fixtures/parity.json";

import { route } from "./binding";
import { applyOp, type FigureOp } from "./ops";
import {
  Rng,
  connectorPath,
  diamondPoints,
  ellipse,
  polygon,
  rectPoints,
} from "./sketch";
import { wrap } from "./text";
import {
  createScene,
  type ConnectorNode,
  type FigureScene,
  type FontFamily,
  type Rect,
  type Routing,
  type Vec,
} from "./scene";

/** Numbers equal within `tol`, everything else structurally equal. */
function close(a: unknown, b: unknown, tol: number, path = "$"): string | null {
  if (typeof a === "number" && typeof b === "number") {
    return Math.abs(a - b) <= tol ? null : `${path}: ${a} != ${b}`;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return `${path}: length ${a.length} != ${b.length}`;
    for (let i = 0; i < a.length; i += 1) {
      const d = close(a[i], b[i], tol, `${path}[${i}]`);
      if (d !== null) return d;
    }
    return null;
  }
  if (typeof a === "object" && a !== null && typeof b === "object" && b !== null) {
    const ao = a as Record<string, unknown>;
    const bo = b as Record<string, unknown>;
    const keys = new Set([...Object.keys(ao), ...Object.keys(bo)]);
    for (const k of keys) {
      if (ao[k] === undefined && bo[k] === undefined) continue;
      const d = close(ao[k], bo[k], tol, `${path}.${k}`);
      if (d !== null) return d;
    }
    return null;
  }
  return a === b ? null : `${path}: ${JSON.stringify(a)} != ${JSON.stringify(b)}`;
}

/**
 * Path strings compare exactly; if a last-digit difference from sin/cos or
 * hypot ever shows up, numbers within 0.11 are accepted and the tolerance
 * is what this function documents.
 */
function samePath(ts: string, rust: string): string | null {
  if (ts === rust) return null;
  const tokens = (s: string) => s.match(/[A-Za-z]|-?\d+(\.\d+)?/g) ?? [];
  const [a, b] = [tokens(ts), tokens(rust)];
  if (a.length !== b.length) return `path shape differs:\n${ts}\n${rust}`;
  for (let i = 0; i < a.length; i += 1) {
    const [x, y] = [a[i] as string, b[i] as string];
    if (/[A-Za-z]/.test(x) || /[A-Za-z]/.test(y)) {
      if (x !== y) return `command ${x} != ${y}`;
    } else if (Math.abs(Number(x) - Number(y)) > 0.11) {
      return `number ${x} != ${y} at token ${i}`;
    }
  }
  return null;
}

interface Step {
  op: FigureOp;
  ok: boolean;
  changed?: string[];
  scene: FigureScene;
}

describe("Rust parity", () => {
  for (const c of fixture.cases as unknown as { name: string; steps: Step[] }[]) {
    it(`ops: ${c.name}`, () => {
      let scene = createScene(960, 540);
      for (const step of c.steps) {
        let ok = true;
        let changed: string[] = [];
        try {
          const result = applyOp(scene, step.op);
          scene = result.scene;
          changed = result.changed;
        } catch {
          ok = false;
        }
        expect(ok, JSON.stringify(step.op)).toBe(step.ok);
        if (ok) expect(changed).toEqual(step.changed);
        expect(close(scene, step.scene, 1e-6), JSON.stringify(step.op)).toBeNull();
      }
    });
  }

  it("seeds", () => {
    for (const s of fixture.seeds) {
      const rng = Rng.forId(s.id);
      expect(s.values.map(() => rng.unit())).toEqual(s.values);
    }
  });

  it("outlines", () => {
    for (const o of fixture.outlines) {
      const rng = Rng.forId(o.seed);
      const r = o.rect as Rect;
      const d =
        o.kind === "rect"
          ? polygon(rectPoints(r), o.roughness, rng)
          : o.kind === "diamond"
            ? polygon(diamondPoints(r), o.roughness, rng)
            : ellipse(r, o.roughness, rng);
      expect(samePath(d, o.d), `${o.kind} ${o.roughness}`).toBeNull();
    }
  });

  it("connectors", () => {
    for (const c of fixture.connectors) {
      const rng = Rng.forId(c.seed);
      const out = connectorPath(
        c.points as Vec[],
        c.routing as Routing,
        (c.ds ?? undefined) as Vec | undefined,
        (c.de ?? undefined) as Vec | undefined,
        c.roughness,
        rng,
      );
      expect(samePath(out.d, c.d), `${c.routing} ${c.roughness}`).toBeNull();
      expect(close(out.startDir, c.startDir, 1e-9)).toBeNull();
      expect(close(out.endDir, c.endDir, 1e-9)).toBeNull();
    }
  });

  it("wraps", () => {
    for (const w of fixture.wraps) {
      expect(wrap(w.text, w.width, w.size, w.family as FontFamily)).toEqual(w.lines);
    }
  });

  it("routes", () => {
    const scene = fixture.routes.scene as unknown as FigureScene;
    for (const r of fixture.routes.cases) {
      const points = route(scene, r.connector as unknown as ConnectorNode);
      expect(close(points, r.points, 1e-6), JSON.stringify(r.connector)).toBeNull();
    }
  });
});
